-- Neon Drift online schema. Run in Supabase > SQL Editor.
create extension if not exists pgcrypto;
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,username text not null unique check(username ~ '^[A-Za-z0-9_]{3,20}$'));
create table if not exists public.friendships(id uuid primary key default gen_random_uuid(),requester_id uuid not null references public.profiles(id) on delete cascade,addressee_id uuid not null references public.profiles(id) on delete cascade,status text not null default 'pending' check(status in('pending','accepted')),created_at timestamptz default now(),unique(requester_id,addressee_id),check(requester_id<>addressee_id));
create table if not exists public.parties(id uuid primary key default gen_random_uuid(),code text not null unique,host_id uuid not null references public.profiles(id) on delete cascade,created_at timestamptz default now());
create table if not exists public.party_members(party_id uuid references public.parties(id) on delete cascade,user_id uuid references public.profiles(id) on delete cascade,is_ready boolean not null default false,joined_at timestamptz default now(),primary key(party_id,user_id));
alter table public.profiles enable row level security;alter table public.friendships enable row level security;alter table public.parties enable row level security;alter table public.party_members enable row level security;
drop policy if exists profile_read on public.profiles;create policy profile_read on public.profiles for select to authenticated using(true);
drop policy if exists profile_update on public.profiles;create policy profile_update on public.profiles for update to authenticated using(auth.uid()=id) with check(auth.uid()=id);
drop policy if exists friendship_read on public.friendships;create policy friendship_read on public.friendships for select to authenticated using(auth.uid() in(requester_id,addressee_id));
drop policy if exists friendship_delete on public.friendships;create policy friendship_delete on public.friendships for delete to authenticated using(auth.uid() in(requester_id,addressee_id));
create or replace function public.neon_is_party_member(pid uuid) returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from public.party_members where party_id=pid and user_id=auth.uid())$$;
drop policy if exists party_read on public.parties;create policy party_read on public.parties for select to authenticated using(public.neon_is_party_member(id));
drop policy if exists party_member_read on public.party_members;create policy party_member_read on public.party_members for select to authenticated using(public.neon_is_party_member(party_id));
create or replace function public.neon_new_profile() returns trigger language plpgsql security definer set search_path=public as $$declare n text;begin n:=left(regexp_replace(coalesce(new.raw_user_meta_data->>'username',split_part(new.email,'@',1)),'[^A-Za-z0-9_]','','g'),20);if length(n)<3 then n:='Pilot'||left(replace(new.id::text,'-',''),8);end if;insert into public.profiles(id,username) values(new.id,n) on conflict(id) do nothing;return new;end$$;
drop trigger if exists neon_profile_after_signup on auth.users;create trigger neon_profile_after_signup after insert on auth.users for each row execute procedure public.neon_new_profile();
create or replace function public.send_friend_request(target_username text) returns text language plpgsql security definer set search_path=public as $$declare target uuid;begin if auth.uid() is null then raise exception 'Sign in first.';end if;select id into target from public.profiles where lower(username)=lower(trim(target_username));if target is null then raise exception 'Username not found.';end if;if target=auth.uid() then raise exception 'Cannot add yourself.';end if;if exists(select 1 from public.friendships where status='accepted' and ((requester_id=auth.uid() and addressee_id=target) or(requester_id=target and addressee_id=auth.uid()))) then raise exception 'Already friends.';end if;if exists(select 1 from public.friendships where status='pending' and ((requester_id=auth.uid() and addressee_id=target) or(requester_id=target and addressee_id=auth.uid()))) then raise exception 'A request already exists.';end if;insert into public.friendships(requester_id,addressee_id) values(auth.uid(),target);return 'Request sent.';end$$;
create or replace function public.respond_friend_request(request_id uuid,accept_request boolean) returns text language plpgsql security definer set search_path=public as $$begin if accept_request then update public.friendships set status='accepted' where id=request_id and addressee_id=auth.uid() and status='pending';else delete from public.friendships where id=request_id and addressee_id=auth.uid() and status='pending';end if;if not found then raise exception 'Request not found.';end if;return 'Updated.';end$$;
create or replace function public.get_my_friends() returns table(friend_id uuid,username text) language sql security definer set search_path=public as $$select p.id,p.username from public.friendships f join public.profiles p on p.id=case when f.requester_id=auth.uid() then f.addressee_id else f.requester_id end where f.status='accepted' and auth.uid() in(f.requester_id,f.addressee_id) order by p.username$$;
create or replace function public.get_friend_requests() returns table(request_id uuid,friend_id uuid,username text,direction text) language sql security definer set search_path=public as $$select f.id,p.id,p.username,case when f.addressee_id=auth.uid() then 'incoming' else 'outgoing' end from public.friendships f join public.profiles p on p.id=case when f.addressee_id=auth.uid() then f.requester_id else f.addressee_id end where f.status='pending' and auth.uid() in(f.requester_id,f.addressee_id) order by f.created_at desc$$;
create or replace function public.create_party() returns table(party_id uuid,party_code text) language plpgsql security definer set search_path=public as $$declare pid uuid;c text;begin if auth.uid() is null then raise exception 'Sign in first.';end if;if exists(select 1 from public.party_members where user_id=auth.uid()) then raise exception 'Leave your current party first.';end if;c:=upper(substr(encode(gen_random_bytes(5),'hex'),1,8));insert into public.parties(code,host_id) values(c,auth.uid()) returning id into pid;insert into public.party_members(party_id,user_id,is_ready) values(pid,auth.uid(),true);return query select pid,c;end$$;
create or replace function public.join_party(join_code text) returns uuid language plpgsql security definer set search_path=public as $$declare pid uuid;begin if auth.uid() is null then raise exception 'Sign in first.';end if;if exists(select 1 from public.party_members where user_id=auth.uid()) then raise exception 'Leave your current party first.';end if;select id into pid from public.parties where code=upper(trim(join_code));if pid is null then raise exception 'Party code not found.';end if;if(select count(*) from public.party_members where party_id=pid)>=4 then raise exception 'Party is full.';end if;insert into public.party_members(party_id,user_id) values(pid,auth.uid());return pid;end$$;
create or replace function public.leave_party() returns text language plpgsql security definer set search_path=public as $$declare pid uuid;host uuid;begin select p.id,p.host_id into pid,host from public.parties p join public.party_members m on m.party_id=p.id where m.user_id=auth.uid();if pid is null then return 'Not in a party.';end if;delete from public.party_members where party_id=pid and user_id=auth.uid();if host=auth.uid() then if exists(select 1 from public.party_members where party_id=pid) then update public.parties set host_id=(select user_id from public.party_members where party_id=pid order by joined_at limit 1) where id=pid;else delete from public.parties where id=pid;end if;elsif not exists(select 1 from public.party_members where party_id=pid) then delete from public.parties where id=pid;end if;return 'Left party.';end$$;
create or replace function public.set_party_ready(ready_state boolean) returns text language plpgsql security definer set search_path=public as $$begin update public.party_members set is_ready=ready_state where user_id=auth.uid();if not found then raise exception 'Not in a party.';end if;return 'Updated.';end$$;
create or replace function public.get_my_party() returns table(party_id uuid,party_code text,host_id uuid,member_id uuid,username text,is_ready boolean) language sql security definer set search_path=public as $$select p.id,p.code,p.host_id,m.user_id,pr.username,m.is_ready from public.party_members mine join public.parties p on p.id=mine.party_id join public.party_members m on m.party_id=p.id join public.profiles pr on pr.id=m.user_id where mine.user_id=auth.uid() order by m.joined_at$$;
grant execute on function public.neon_is_party_member(uuid) to authenticated;
grant execute on function public.send_friend_request(text) to authenticated;
grant execute on function public.respond_friend_request(uuid,boolean) to authenticated;
grant execute on function public.get_my_friends() to authenticated;
grant execute on function public.get_friend_requests() to authenticated;
grant execute on function public.create_party() to authenticated;
grant execute on function public.join_party(text) to authenticated;
grant execute on function public.leave_party() to authenticated;
grant execute on function public.set_party_ready(boolean) to authenticated;
grant execute on function public.get_my_party() to authenticated;
do $$begin alter publication supabase_realtime add table public.party_members;exception when duplicate_object then null;when undefined_object then null;end$$;
